// Node's own resolution rule sends this require to vt2-init-lib's OWN
// node_modules, not the top-level one: a package's private tree is
// searched before its parents'. The two installs are identical in name,
// version and vulnerable export name, and distinguishable only by path.
const dep = require("vt2-vuln-lib");

// A private helper that exists only to share the vulnerable export's
// spelling (RWF-011). Nothing publishes it, nothing calls it, and it is
// declared BEFORE everything real -- so both a same-file bare-name search
// and a "first function in the file" heuristic land here.
function dangerousOp(input) {
  return "decoy:" + input;
}

// The branch that reaches the vulnerable package. Nothing in this file
// calls it: the ONLY way it ever runs is by being this module's exported
// value.
function fastPath(input) {
  return dep.dangerousOp(input);
}

// The branch that does not.
function slowPath(input) {
  return "slow:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// throw. This is RWF-016's callee, unchanged -- what RWF-024 is about is
// the POSITION the call is written in, below: an OBJECT LITERAL's
// COMPUTED KEY, on an object literal that is not part of any class.
function bail() {
  throw new Error("fast mode is not supported by this build");
}

// A harmless key callee that RETURNS NORMALLY. An analyzer that fires on
// "a computed key in an object literal" rather than on "a computed key
// whose call this file proves can only throw" cuts the module off here
// and is wrong.
function safeKey() {
  return "installed";
}

// A same-name decoy nested inside a function that is never called at
// module scope. Real JS lexical scoping never resolves the module-scope
// call below to this one, and the deferred object literal never runs at
// load time either -- so it changes no answer, and the oracle does not
// depend on it.
function configure() {
  function bail() {
    return "safe";
  }
  // A computed key carrying the exact RWF-024 shape, DEFERRED inside a
  // function body: `configure` is never called at module scope, so this
  // object literal is never evaluated during module evaluation and must
  // poison nothing.
  return {
    [bail()]: 1,
  };
}

// An ALIAS and a MEMBER callee, inside a function nothing calls at module
// scope. Neither is resolved by this analyzer's exact-local-callee model,
// which is conservatively correct either way since this probe never runs.
function probeIndirect() {
  const alias = bail;
  const holder = { make: bail };
  return {
    viaAlias: { [alias()]: 1 },
    viaMember: { [holder.make()]: 1 },
  };
}

// An object literal carrying the identical always-throwing call in the two
// positions the language genuinely defers for an object literal: a
// method's BODY (runs only when called) and a getter's BODY (runs only
// when read). Evaluating this object literal installs both and executes
// neither.
const probe = {
  safeMethod() {
    return "ok";
  },
  lazy() {
    return bail();
  },
  get lazyGetter() {
    return bail();
  },
};

// A computed key whose call is CONDITIONAL, evaluated at module scope. It
// genuinely may not call `bail` at all -- confirmed under real `node` with
// a falsy flag, where the object literal completed. Refusing to treat this
// as abrupt is correct, not a gap.
const conditionalProbe = {
  [process.env.VT2_CONDITION === "yes" ? bail() : "harmless"]: 1,
};

if (process.env.VT2_MODE === "fast") {
  module.exports = fastPath;
  // The RWF-024 shape, and note what it is NOT: there is no class, no
  // `static` token and no class element anywhere near it. The call is an
  // OBJECT LITERAL's COMPUTED KEY, evaluated as the object literal is
  // constructed -- which is part of module evaluation, in source order,
  // exactly like every earlier statement in this file. So reaching this
  // declaration necessarily invokes `bail`, which never returns; `mode` is
  // never bound, and module evaluation on this branch ends here.
  const mode = {
    [safeKey()]: "installed",
    [bail()]: 1,
  };
  void mode;
}

// Reached on every OTHER load, and on no load where the branch above was
// taken. Syntactically this is exactly what RWF-014 accepted: a bare
// identifier assigned by an unconditional top-level statement, last in the
// file, with no deferred write anywhere -- and RWF-015's return/throw
// cutoff, RWF-016's bare-call cutoff, RWF-017's variable-initializer
// cutoff, RWF-018's static-field cutoff, RWF-019's computed-class-key
// cutoff, RWF-020's heritage cutoff and RWF-022's invalid-heritage-value
// cutoff all find nothing here to object to either, since the file
// contains no module-scope `return`/`throw`, no bare `bail();` statement,
// no `const x = bail();` declaration and no `class` anywhere at all.
module.exports = slowPath;

void configure;
void probeIndirect;
void probe;
void conditionalProbe;
